from functools import cache

def word_break(s, word_dict):
    @cache
    def can_split(start):                 # can s[start:] be split?
        if start == len(s):
            return True
        return any(s.startswith(w, start) and can_split(start + len(w)) for w in word_dict)

    return can_split(0)

