function wordBreak(s, wordDict) {
  const words = new Set(wordDict);
  const longest = Math.max(...wordDict.map((w) => w.length));
  // dp[i]: can the first i letters, s[0..i), be split into dictionary words?
  const dp = new Array(s.length + 1).fill(false);
  dp[0] = true;                                   // the empty prefix needs no words
  for (let i = 1; i <= s.length; i++) {
    for (let j = Math.max(0, i - longest); j < i; j++) {
      if (dp[j] && words.has(s.slice(j, i))) {    // a good split up to j, then one word
        dp[i] = true;
        break;
      }
    }
  }
  return dp[s.length];
}

boolean wordBreak(String s, List<String> wordDict) {
    Set<String> words = new HashSet<>(wordDict);
    int longest = 0;
    for (String w : wordDict) longest = Math.max(longest, w.length());
    // dp[i]: can the first i letters, s[0..i), be split into dictionary words?
    boolean[] dp = new boolean[s.length() + 1];
    dp[0] = true;                                    // the empty prefix needs no words
    for (int i = 1; i <= s.length(); i++) {
        for (int j = Math.max(0, i - longest); j < i; j++) {
            if (dp[j] && words.contains(s.substring(j, i))) {   // a good split up to j, then one word
                dp[i] = true;
                break;
            }
        }
    }
    return dp[s.length()];
}

bool wordBreak(string s, vector<string>& wordDict) {
    unordered_set<string> words(wordDict.begin(), wordDict.end());
    int longest = 0;
    for (const string& w : wordDict) longest = max(longest, (int)w.size());
    // dp[i]: can the first i letters, s[0..i), be split into dictionary words?
    vector<bool> dp(s.size() + 1, false);
    dp[0] = true;                                    // the empty prefix needs no words
    for (int i = 1; i <= (int)s.size(); i++) {
        for (int j = max(0, i - longest); j < i; j++) {
            if (dp[j] && words.count(s.substr(j, i - j))) {   // a good split up to j, then one word
                dp[i] = true;
                break;
            }
        }
    }
    return dp[s.size()];
}
